114	func AcquireRetrievalPrivacyPolicies(policies []RetrievalPrivacyPolicy, requireDerivedClean func(string) error) (func(), error) {
115		byBrain, derivedClean, brainDirs, err := normalizeRetrievalPrivacyPolicies(policies)
116		if err != nil {
117			return nil, err
118		}
119		unlocks := make([]func(), 0, len(brainDirs))
120		for _, brainDir := range brainDirs {
121			unlock, err := AcquireBrainWriteLock(brainDir)
122			if err != nil {
123				for i := len(unlocks) - 1; i >= 0; i-- {
124					unlocks[i]()
125				}
126				return nil, err
127			}
128			unlocks = append(unlocks, unlock)
129		}
130		release := func() {
131			for i := len(unlocks) - 1; i >= 0; i-- {
132				unlocks[i]()
133			}
134		}
135		if err := validateNormalizedRetrievalPolicies(byBrain, derivedClean, brainDirs, requireDerivedClean); err != nil {
136			release()
137			return nil, err
138		}
139		return release, nil
140	}
