40				if policy.BrainDir == "" {
41					continue
42				}
43				if err := requirePrivacyDerivedRead(policy.BrainDir); err != nil {
44					return err
45				}
46			}
47			if err := mutate(); err != nil {
48				return err
49			}
50			cmd.SetOut(originalOut)
51			cmd.SetErr(originalErr)
52			if err := writeAllCommandBytes(originalOut, stdout.Bytes()); err != nil {
53				return err
54			}
55			return writeAllCommandBytes(originalErr, stderr.Bytes())
56		})
57	}
58	
59	func writeAllCommandBytes(out io.Writer, data []byte) error {
60		if len(data) == 0 {
61			return nil
62		}
63		n, err := out.Write(data)
64		if err == nil && n != len(data) {
65			return io.ErrShortWrite
66		}
67		if err != nil {
68			return fmt.Errorf("write command output: %w", err)
69		}
70		return nil
71	}
