746	// buildSessionPurgePlan computes exactly what a purge touches, from the
747	// trusted manifest and the current index. Purging an unknown or already-purged
748	// session yields an empty plan (idempotent), not an error.
749	func loadAllFactBranchesForPrivacy(brainDir string) (map[string][]factRecord, error) {
750		entries, present, err := brainstore.ReadPrivacyDirectory(brainDir, factstore.DirName, "facts directory")
751		if err != nil || !present {
752			if err != nil {
753				return nil, err
754			}
755			return map[string][]factRecord{}, nil
756		}
757		byBranch := map[string][]factRecord{}
758		for _, entry := range entries {
759			if entry.Type()&os.ModeSymlink != 0 {
760				return nil, fmt.Errorf("%s: facts inventory contains a symlink: %s", brainstore.StateUnsafeCode, entry.Name())
761			}
762			info, err := entry.Info()
763			if err != nil {
764				return nil, fmt.Errorf("%s: inspect facts entry %s: %w", brainstore.StateCorruptCode, entry.Name(), err)
765			}
766			if !info.IsDir() {
767				if !info.Mode().IsRegular() {
768					return nil, fmt.Errorf("%s: facts inventory contains a nonregular entry: %s", brainstore.StateUnsafeCode, entry.Name())
769				}
770				continue // taxonomy and other root-level metadata are not fact stores.
771			}
772			rel := filepath.ToSlash(filepath.Join(factstore.DirName, entry.Name(), factstore.FileName))
773			data, exists, err := brainstore.ReadPrivacyArtifact(brainDir, rel, "fact store", 256<<20)
774			if err != nil {
775				return nil, err
776			}
777			if exists {
778				for lineNumber, line := range strings.Split(string(data), "\n") {
779					trimmed := strings.TrimSpace(line)
780					if trimmed == "" {
781						continue
782					}
783					var record factRecord
784					if err := json.Unmarshal([]byte(trimmed), &record); err != nil {
785						return nil, fmt.Errorf("%s: parse %s line %d: %w", brainstore.StateCorruptCode, rel, lineNumber+1, err)
786					}
787					byBranch[record.Branch] = append(byBranch[record.Branch], record)
788				}
789			}
790			proposalRel := filepath.ToSlash(filepath.Join(factstore.DirName, entry.Name(), factsProposalsFileName))
791			proposalData, proposalExists, err := brainstore.ReadPrivacyArtifact(brainDir, proposalRel, "fact proposal store", 64<<20)
792			if err != nil {
793				return nil, err
794			}
795			if proposalExists {
796				for lineNumber, line := range strings.Split(string(proposalData), "\n") {
797					trimmed := strings.TrimSpace(line)
798					if trimmed == "" {
799						continue
800					}
801					var proposal factProposal
802					if err := json.Unmarshal([]byte(trimmed), &proposal); err != nil {
803						return nil, fmt.Errorf("%s: parse %s line %d: %w", brainstore.StateCorruptCode, proposalRel, lineNumber+1, err)
804					}
805				}
806			}
807		}
808		// Inspect physical snapshot bodies, not the reconciled view. Old clients
809		// can delete a legacy record while leaving its snapshot body behind.
810		stored, err := factstore.StoredRepositoryRecords(brainDir)
811		if err != nil {
812			return nil, err
813		}
814	
815		if len(stored) != 0 {
816			seen := map[string]bool{}
817			for _, records := range byBranch {
818				for _, rec := range records {
819					data, err := json.Marshal(rec)
820					if err != nil {
821						return nil, err
822					}
823					seen[string(data)] = true
824				}
825			}
826			for _, rec := range stored {
827				data, err := json.Marshal(rec)
828				if err != nil {
829					return nil, err
830				}
831				if !seen[string(data)] {
832					byBranch[rec.Branch] = append(byBranch[rec.Branch], rec)
833					seen[string(data)] = true
834				}
835			}
836		}
837	
838		return byBranch, nil
839	}
