849	func buildSessionPurgePlan(brainDir, sessionID string) (sessionPurgePlan, error) {
850		plan := sessionPurgePlan{SessionID: sessionID}
851		manifest, err := bmanifest.Load(brainDir)
852		if err != nil {
853			return plan, err
854		}
855		refSet := sessionRefsForSessionID(brainDir, manifest, sessionID)
856		priorTx, priorPresent, err := brainstore.LoadPrivacyTransactionChecked(brainDir, sessionID)
857		if err != nil {
858			return plan, err
859		}
860		if priorPresent {
861			for _, ref := range priorTx.SessionRefs {
862				refSet[ref] = true
863			}
864		}
865		transcriptRels := map[string]bool{}
866		priorPaths, err := brainstore.PrivacyTransactionTranscriptPaths(priorTx)
867		if err != nil {
868			return plan, err
869		}
870		for _, rel := range priorPaths {
871			transcriptRels[rel] = true
872		}
873		if manifest.Sources != nil && manifest.Sources.Sessions != nil {
874			for _, session := range manifest.Sources.Sessions.Sessions {
875				if strings.TrimSpace(session.SessionID) == sessionID {
876					if rel := brainstore.NormalizePrivacyTranscriptPath(session.TranscriptPath); rel != "" {
877						transcriptRels[rel] = true
878					}
879				}
880			}
881		}
882		// Keep missing paths in the durable scope too: a later re-export must
883		// remain detectable even after the manifest has forgotten this session.
884		for rel := range transcriptRels {
885			artifact := purgeArtifact{Path: rel}
886			info, present, statErr := brainstore.PrivacyArtifactInfo(brainDir, rel, "session transcript")
887			if statErr != nil {
888				return plan, statErr
889			}
890			if present {
891				artifact.Bytes = info.Size()
892			}
893			plan.Transcripts = append(plan.Transcripts, artifact)
894		}
895		sort.Slice(plan.Transcripts, func(i, j int) bool { return plan.Transcripts[i].Path < plan.Transcripts[j].Path })
896		if manifest.Sources != nil && manifest.Sources.History != nil {
897			// A declared-but-unreadable index is a real storage problem: failing
898			// here beats an under-reported plan that execution would then trust
899			// (dry-run and execution inventories must match).
900			index, ierr := historystore.LoadIndex(brainDir, manifest.Sources.History)
901			if ierr != nil {
902				return plan, fmt.Errorf("load history index: %w", ierr)
903			}
904			for _, record := range index.Records {
905				if transcriptRels[record.Path] {
906					plan.Records++
907				}
908			}
909		}
910		// Facts derived from the purged session (single-source facts are deleted;
911		// multi-source facts only lose the purged anchor). A corrupt fact store is
912		// an error, not an empty count.
913		byBranch, ferr := loadAllFactBranchesForPrivacy(brainDir)
914		if ferr != nil {
915			return plan, fmt.Errorf("load facts: %w", ferr)
916		}
917		for _, facts := range byBranch {
918			for _, fact := range facts {
919				matched, remaining := 0, 0
920				for _, anchor := range fact.Provenance {
921					if factAnchorMatchesSession(anchor, sessionID, transcriptRels) {
922						matched++
923					} else {
924						remaining++
925					}
926				}
927				switch {
928				case matched > 0 && remaining == 0:
929					plan.FactsDeleted++
930				case matched > 0:
931					plan.FactAnchorsStripped += matched
932				}
933			}
934		}
935		// Pattern-layer episodes derived from the session.
936		plan.Episodes, err = countSessionEpisodes(brainDir, sessionID, transcriptRels)
937		if err != nil {
938			return plan, err
939		}
940		// Rebuildable derived stores removed wholesale: their row-level content is
941		// keyed by record ids/text derived from the purged transcripts, and every
942		// one regenerates from the surviving truth (index rebuild, lazy FTS build,
943		// next vector sync, next patterns build). runs.ndjson is a build log and
944		// logs are inside the plan's deletion inventory.
945		derivedArtifacts, inventoryErr := privacyDerivedStoreArtifacts(brainDir)
946		if inventoryErr != nil {
947			return plan, inventoryErr
948		}
949		for _, rel := range derivedArtifacts {
950			info, present, statErr := brainstore.PrivacyArtifactInfo(brainDir, rel, "derived privacy store")
951			if statErr != nil {
952				return plan, statErr
953			}
954			if present {
955				plan.DerivedStores = append(plan.DerivedStores, purgeArtifact{Path: rel, Bytes: info.Size()})
956			}
957		}
958		// Durable memory hints/jobs are intentionally content-free, but they still
959		// retain the identity and lifecycle of this session. Include their exact
960		// files in dry-run and execution inventories so privacy cleanup is complete
961		// and auditable.
962		hints, hintIssues := loadMemoryHintsChecked(brainDir)
963		jobInventory := loadMemoryJobInventory(brainDir)
964		if err := memoryStateError(append(hintIssues, jobInventory.Issues...)); err != nil {
965			return plan, err
966		}
967		addWork := func(rel string) error {
968			artifact := purgeArtifact{Path: rel}
969			info, present, statErr := brainstore.PrivacyArtifactInfo(brainDir, rel, "memory work metadata")
970			if statErr != nil {
971				return statErr
972			}
973			if present {
974				artifact.Bytes = info.Size()
975			}
976			plan.WorkMetadata = append(plan.WorkMetadata, artifact)
977			return nil
978		}
979		for _, hint := range hints {
980			if hint.SessionID == sessionID {
981				if err := addWork(memoryHintRel(hint.RepoKey, hint.SessionID, hint.Branch)); err != nil {
982					return plan, err
983				}
984			}
985		}
986		for _, job := range jobInventory.Jobs {
987			if job.SessionID != sessionID {
988				continue
989			}
990			if ref := strings.TrimSpace(job.SessionRef); ref != "" {
991				if !strings.HasPrefix(ref, brainstore.ConversationSessionIDPrefix) {
992					return plan, fmt.Errorf("%s: abstract job has invalid session ref", brainstore.StateCorruptCode)
993				}
994				refSet[ref] = true
995			}
996			for _, rel := range memoryJobSourcePaths(job) {
997				if err := addWork(rel); err != nil {
998					return plan, err
999				}
1000			}
1001			cancellationRel := memoryCancellationRel(job.JobID)
1002			_, present, statErr := brainstore.PrivacyArtifactInfo(brainDir, cancellationRel, "memory cancellation marker")
1003			if statErr != nil {
1004				return plan, statErr
1005			}
1006			if present {
1007				if err := addWork(cancellationRel); err != nil {
1008					return plan, err
1009				}
1010			}
1011		}
1012		if len(refSet) > brainstore.PrivacyTransactionSessionRefMax {
1013			return plan, fmt.Errorf("%s: privacy scope exceeds %d canonical session refs", brainstore.QueryTooBroadCode, brainstore.PrivacyTransactionSessionRefMax)
1014		}
1015		for ref := range refSet {
1016			plan.SessionRefs = append(plan.SessionRefs, ref)
1017		}
1018		sort.Strings(plan.SessionRefs)
1019		egressReceipts, egressErr := abstractEgressReceiptsForSessionRefsChecked(brainDir, refSet)
1020		if egressErr != nil {
1021			return plan, egressErr
1022		}
1023		for _, receipt := range egressReceipts {
1024			if err := addWork(receipt.Path); err != nil {
1025				return plan, err
1026			}
1027		}
1028		sort.Slice(plan.WorkMetadata, func(i, j int) bool { return plan.WorkMetadata[i].Path < plan.WorkMetadata[j].Path })
1029		return plan, nil
1030	}
1031	
1032	// privacyDerivedStoreRels is the static inventory of rebuildable derived
1033	// stores that exclude/purge delete wholesale and `privacy verify` re-checks;
1034	// dry-run, execution, and verification must never disagree on this list.
1035	func privacyDerivedStoreRels() []string {
1036		rels := []string{
1037			historyFTSDBRelPath(),
1038			filepath.ToSlash(filepath.Join(brainstore.HistoryDirName, historyScanCacheFileName)),
1039			historyShortTermPath,
1040			filepath.ToSlash(filepath.Join(brainstore.HistoryDirName, embedStoreDirName, historyVecStoreFileNamePortable)),
1041			filepath.ToSlash(filepath.Join(brainstore.HistoryDirName, embedStoreDirName, conversationVecStoreFileNamePortable)),
1042			patternsTasksPath,
1043			patterncore.ProceduresPath,
1044			patterncore.PracticesPath,
1045			patterncore.RunsRelPath,
1046		}
1047		rels = append(rels, patterncore.CorpusPrivacyArtifactRels()...)
1048		rels = append(rels, patterncore.CorpusPublicationMarkerPath)
1049		return rels
1050	}
1051	
1052	// privacyDerivedStoreArtifacts expands the static inventory with the
1053	// per-branch fact embedding caches (embeddings of distilled fact text; a
1054	// purged session's facts may be partially recoverable from them) and the
1055	// SQLite WAL/SHM siblings of every ordinary store and the publication layer's
1056	// canonical WAL/SHM/rollback-journal set for the pattern corpus, so dry-run
1057	// reports and cleanup delete exactly the same artifact set, orphans included.
1058	func privacyDerivedStoreArtifacts(brainDir string) ([]string, error) {
1059		rels := privacyDerivedStoreRels()
1060		publication, _, publicationPresent, err := patterncore.LoadCorpusPublicationForPrivacy(brainDir)
1061		if err != nil {
1062			return nil, err
1063		}
1064		if publicationPresent {
1065			// Inventory the marker-authorized candidate even if it disappears before
1066			// the directory scan. A current marker is valid operational state, but
1067			// both leaves are transient/content-bearing and privacy cleanup owns them.
1068			rels = append(rels, filepath.ToSlash(filepath.Join("patterns", publication.Candidate)))
1069		}
1070		manifest, err := bmanifest.Load(brainDir)
1071		if err != nil {
1072			return nil, err
1073		}
1074		activeIndex, activeReceipt := "", ""
1075		if manifest.Sources != nil && manifest.Sources.History != nil {
1076			activeIndex = filepath.ToSlash(strings.TrimSpace(manifest.Sources.History.IndexPath))
1077			activeReceipt = filepath.ToSlash(strings.TrimSpace(manifest.Sources.History.ProjectionStatePath))
1078			if activeReceipt == "" && manifest.Sources.History.ProjectionStateDigest != "" {
1079				activeReceipt = projectionStateRel
1080			}
1081		}
1082		for _, legacy := range []struct {
1083			path   string
1084			active string
1085		}{{historystore.IndexPath, activeIndex}, {projectionStateRel, activeReceipt}} {
1086			if legacy.path == legacy.active {
1087				continue
1088			}
1089			info, statErr := brainstore.PrivacyLstat(filepath.Join(brainDir, filepath.FromSlash(legacy.path)))
1090			if statErr != nil {
1091				if os.IsNotExist(statErr) {
1092					continue
1093				}
1094				return nil, fmt.Errorf("memory_state_corrupt: inventory legacy projection %s: %w", legacy.path, statErr)
1095			}
1096			if info.Mode()&os.ModeSymlink != 0 || !info.Mode().IsRegular() {
1097				return nil, fmt.Errorf("memory_state_corrupt: inactive legacy projection is not a regular file: %s", legacy.path)
1098			}
1099			rels = append(rels, legacy.path)
1100		}
1101		// History generations are immutable publication artifacts. Every old
1102		// generation may still contain the excluded session even though only one is
1103		// manifest-referenced, so privacy cleanup inventories and deletes them all.
1104		for _, rootRel := range []string{historystore.GenerationsDir, historystore.StagingDir} {
1105			root := filepath.Join(brainDir, filepath.FromSlash(rootRel))
1106			err := privacyWalkDir(root, func(path string, d fs.DirEntry, walkErr error) error {
1107				if walkErr != nil {
1108					return walkErr
1109				}
1110				if d.Type()&os.ModeSymlink != 0 {
1111					return fmt.Errorf("memory_state_corrupt: history projection inventory contains a symlink: %s", path)
1112				}
1113				if d.IsDir() {
1114					return nil
1115				}
1116				info, infoErr := d.Info()
1117				if infoErr != nil {
1118					return infoErr
1119				}
1120				if !info.Mode().IsRegular() {
1121					return fmt.Errorf("memory_state_corrupt: history projection inventory contains a nonregular artifact: %s", path)
1122				}
1123				if rel, relErr := filepath.Rel(brainDir, path); relErr == nil {
1124					rel = filepath.ToSlash(rel)
1125					if historystore.ValidGenerationArtifactPath(rel, historystore.IndexFileName) || historystore.ValidGenerationArtifactPath(rel, projectionStateFileName) ||
1126						historystore.ValidStagingArtifactPath(rel, historystore.IndexFileName) || historystore.ValidStagingArtifactPath(rel, projectionStateFileName) {
1127						if rel == activeIndex || rel == activeReceipt {
1128							return nil
1129						}
1130						rels = append(rels, rel)
1131						return nil
1132					}
1133				}
1134				return fmt.Errorf("memory_state_corrupt: unknown history projection artifact: %s", path)
1135			})
1136			if err != nil && !os.IsNotExist(err) {
1137				return nil, fmt.Errorf("memory_state_corrupt: inventory %s: %w", rootRel, err)
1138			}
1139		}
1140		// A pattern rebuild is assembled beside the corpus before one transactional
1141		// publication. A crash can leave its randomly named main/WAL/SHM/journal leaves
1142		// behind, and an in-flight build may still contain an excluded transcript.
1143		// Inventory the bounded directory explicitly so purge removes every such
1144		// staging generation and the later publisher fails closed.
1145		patternEntries, patternsPresent, err := brainstore.ReadPrivacyDirectory(brainDir, "patterns", "pattern directory")
1146		if err != nil {
1147			return nil, err
1148		}
1149		if patternsPresent {
1150			for _, entry := range patternEntries {
1151				if !strings.HasPrefix(entry.Name(), patterncore.CorpusStagingPrefix) {
1152					continue
1153				}
1154				if entry.Type()&os.ModeSymlink != 0 {
1155					return nil, fmt.Errorf("%s: pattern staging inventory contains a symlink: %s", brainstore.StateUnsafeCode, entry.Name())
1156				}
1157				info, infoErr := entry.Info()
1158				if infoErr != nil {
1159					return nil, fmt.Errorf("%s: inspect pattern staging artifact %s: %w", brainstore.StateCorruptCode, entry.Name(), infoErr)
1160				}
1161				if !info.Mode().IsRegular() {
1162					return nil, fmt.Errorf("%s: pattern staging inventory contains a nonregular artifact: %s", brainstore.StateUnsafeCode, entry.Name())
1163				}
1164				rels = append(rels, filepath.ToSlash(filepath.Join("patterns", entry.Name())))
1165			}
1166		}
1167		// Discover fact-vector caches by directory entries, never by Glob: branch
1168		// names may contain glob metacharacters, and Glob cannot report unreadable
1169		// directories or unsafe entry types. Only the two exact store basenames and
1170		// their SQLite sidecars are allowed in an embeddings directory.
1171		factEntries, factsPresent, err := brainstore.ReadPrivacyDirectory(brainDir, factstore.DirName, "facts directory")
1172		if err != nil {
1173			return nil, err
1174		}
1175		if factsPresent {
1176			for _, branchEntry := range factEntries {
1177				if branchEntry.Type()&os.ModeSymlink != 0 {
1178					return nil, fmt.Errorf("%s: facts inventory contains a symlink: %s", brainstore.StateUnsafeCode, branchEntry.Name())
1179				}
1180				branchInfo, infoErr := branchEntry.Info()
1181				if infoErr != nil {
1182					return nil, fmt.Errorf("%s: inspect facts entry %s: %w", brainstore.StateCorruptCode, branchEntry.Name(), infoErr)
1183				}
1184				if !branchInfo.IsDir() {
1185					if !branchInfo.Mode().IsRegular() {
1186						return nil, fmt.Errorf("%s: facts inventory contains a nonregular entry: %s", brainstore.StateUnsafeCode, branchEntry.Name())
1187					}
1188					continue
1189				}
1190				embedRel := filepath.ToSlash(filepath.Join(factstore.DirName, branchEntry.Name(), embedStoreDirName))
1191				embedEntries, embedPresent, readErr := brainstore.ReadPrivacyDirectory(brainDir, embedRel, "fact embedding directory")
1192				if readErr != nil {
1193					return nil, readErr
1194				}

