18	// beforeRetrievalResponsePrivacyRecheck is a deterministic race seam for
19	// tests. Production leaves it as a no-op. It runs after ranking and immediately
20	// before the authoritative pre-emission privacy check.
21	var beforeRetrievalResponsePrivacyRecheck = func() {}
22	
23	// beforeRetrievalResponsePrivacyEmissionCheck is the final transport-boundary
24	// race seam. Production leaves it as a no-op; tests use it to land a tombstone
25	// after the complete response has been buffered but before any byte is written.
26	var beforeRetrievalResponsePrivacyEmissionCheck = func() {}
27	
28	// The retrieval privacy policy lives in brainstore; the alias keeps the
29	// package-local name for the many existing readers and tests.
30	type retrievalPrivacyPolicy = brainstore.RetrievalPrivacyPolicy
31	
32	// bufferRetrievalCommandOutput preserves each command's exact legacy bytes
33	// while moving the authoritative privacy check to one shared final boundary.
34	// Rendering failures discard the private buffer and emit nothing.
35	func bufferRetrievalCommandOutput(cmd *cobra.Command, policies []retrievalPrivacyPolicy, render func() error) error {
36		original := cmd.OutOrStdout()
37		var buffered bytes.Buffer
38		cmd.SetOut(&buffered)
39		defer cmd.SetOut(original)
40		if err := render(); err != nil {
41			return err
42		}
43		cmd.SetOut(original)
44		return writeRetrievalResponseBytes(original, buffered.Bytes(), policies...)
45	}
46	
47	// privacyCheckedWriter is for an interactive surface that cannot buffer its
48	// entire lifetime (the dashboard TUI). Each terminal write revalidates the
49	// captured policy; once policy changes, the next draw fails closed.
50	type privacyCheckedWriter struct {
51		out      io.Writer
52		policies []retrievalPrivacyPolicy
53	}
54	
55	func (w privacyCheckedWriter) Write(p []byte) (int, error) {
56		err := writeRetrievalResponseBytes(w.out, p, w.policies...)
57		if err != nil {
58			return 0, err
59		}
60		return len(p), nil
61	}
62	
63	// writeRetrievalResponseBytes is the only final write boundary for retrieval,
64	// get, brief, and workspace payloads. Callers must buffer the exact response
65	// first. A policy change never produces a partial stale response: every checked
66	// brain is revalidated before the first byte is handed to the consumer.
67	func writeRetrievalResponseBytes(out io.Writer, data []byte, policies ...retrievalPrivacyPolicy) error {
68		return commitRetrievalResponse(policies, func() error {
69			n, err := out.Write(data)
70			if err == nil && n != len(data) {
71				return io.ErrShortWrite
72			}
73			return err
74		})
75	}
76	
77	// withLockedRetrievalPrivacyPolicies is the mutation-side policy boundary
78	// (brainstore owns the lock ordering and identity revalidation); the CLI
79	// adapters bind the derived-read gate. Read-response emission validates
80	// without locks via commitRetrievalResponse instead.
81	func withLockedRetrievalPrivacyPolicies(policies []retrievalPrivacyPolicy, fn func() error) error {
82		return brainstore.WithLockedRetrievalPrivacyPolicies(policies, requirePrivacyDerivedRead, fn)
83	}
84	
85	// commitRetrievalResponse revalidates the captured policies (no lock — see
86	// ValidateRetrievalPrivacyPolicies for the retired linearization story) and
87	// then commits the buffered response. The CLI surfaces reach it through
88	// writeRetrievalResponseBytes; the viz HTTP transport uses it directly
89	// (injected as viz.Deps.CommitRetrievalResponse).
90	func commitRetrievalResponse(policies []retrievalPrivacyPolicy, write func() error) error {
91		beforeRetrievalResponsePrivacyEmissionCheck()
92		if err := brainstore.ValidateRetrievalPrivacyPolicies(policies, requirePrivacyDerivedRead); err != nil {
93			return err
94		}
95		return write()
96	}
97	
98	// revalidateRetrievalResponsePrivacy closes the ranking-to-write window. A
99	// tombstone that appears after ranking either makes the authoritative derived
100	// state dirty (and fails the response closed) or is fully cleaned and reaches
101	// the freshly loaded session guard below.
102	func revalidateRetrievalResponsePrivacy(brainDir string, results []unifiedResult) ([]unifiedResult, string, error) {
103		beforeRetrievalResponsePrivacyRecheck()
104		allowed, err := privacyDerivedReadGate(brainDir)
105		if err != nil {
106			return nil, "", err
107		}
108		if !allowed {
109			return nil, "", fmt.Errorf("%s: retrieval state changed after ranking; retry after excluded-session cleanup verifies clean", brainstore.PrivacyDirtyCode)
110		}
111		manifest, err := bmanifest.Load(brainDir)
112		if err != nil {
113			return nil, "", err
114		}
115		guard, err := bmanifest.LoadSessionReadGuard(brainDir, manifest)
116		if err != nil {
117			return nil, "", err
118		}
119		if len(results) == 0 {
120			return results, guard.PolicyIdentity, nil
121		}
122		if guard.Empty() {
123			return results, guard.PolicyIdentity, nil
124		}
125	
126		// A completed exclusion deliberately retains canonical transcripts, so a
127		// clean derived-state verification alone is insufficient. Rebuild the
128		// allowed virtual-session set through the fresh guard and drop any response
129		// row whose direct or nested conversation proof is no longer readable.
130		allowedRefs := map[string]bool{}
131		allowedEvidence := map[string]bool{}
132		if manifest.Sources != nil && manifest.Sources.History != nil {
133			fresh, loadErr := loadFreshHistory(brainDir, manifest.Sources.History)
134			if loadErr != nil {
135				return nil, "", fmt.Errorf("load history for privacy recheck: %w", loadErr)
136			}
137			for ref, view := range buildConversationSessionViews(fresh, manifest.RepoKey, manifest, guard) {
138				allowedRefs[ref] = true
139				for _, record := range view.Records {
140					allowedEvidence[record.ID] = true
141				}
142			}
143		}
144		kept := make([]unifiedResult, 0, len(results))
145		for _, result := range results {
146			if guard.BlocksSession(result.SessionID) || historystore.GuardBlocksRecord(guard, historyRecord{Path: result.Path}) {
147				continue
148			}
149			if result.SessionRef != "" && !allowedRefs[result.SessionRef] {
150				continue
151			}
152			blockedProof := false
153			for _, id := range result.EvidenceIDs {
154				if strings.HasPrefix(id, conversationIDPrefix) && !allowedEvidence[id] {
155					blockedProof = true
156					break
157				}
158			}
159			if !blockedProof {
160				for _, match := range result.ConceptMatches {
161					if strings.HasPrefix(match.ConversationID, conversationIDPrefix) && !allowedEvidence[match.ConversationID] {
162						blockedProof = true
163						break
164					}
165				}
166			}
167			if !blockedProof {
168				kept = append(kept, result)
169			}
170		}
171		return kept, guard.PolicyIdentity, nil
172	}
