174	func filterAbstractPreviewsForRows(previews []sessionAbstractPreview, rows []compactUnifiedResult) ([]sessionAbstractPreview, bool) {
175		if len(previews) == 0 {
176			return nil, false
177		}
178		refs := make(map[string]bool, len(rows))
179		for _, row := range rows {
180			if row.SessionRef != "" {
181				refs[row.SessionRef] = true
182			}
183		}
184		out := make([]sessionAbstractPreview, 0, len(previews))
185		for _, preview := range previews {
186			if refs[preview.SessionRef] {
187				out = append(out, preview)
188			}
189		}
190		return out, len(out) != len(previews)
191	}
