193	func buildRetrievalJSONPayload(query, branch string, rows []compactUnifiedResult, extras retrievalTransportExtras, truncated bool) map[string]any {
194		payload := map[string]any{"query": query, "branch": branch, "results": rows}
195		if truncated {
196			payload["response_truncated"] = true
197			if len(rows) > 0 {
198				// Preserve the additive row marker shipped by the initial multi-concept surface,
199				// while making the envelope marker usable even when zero rows fit.
200				rows[len(rows)-1].ResponseTruncated = true
201				payload["results"] = rows
202			}
203		}
204		if previews, cut := filterAbstractPreviewsForRows(extras.AbstractPreviews, rows); len(previews) > 0 || extras.AbstractPreviews != nil {
205			payload["abstract_previews"] = previews
206			payload["abstract_previews_truncated"] = extras.AbstractPreviewsTruncated || cut
207		}
208		if len(extras.Hints.LikelyEditFiles) > 0 {
209			payload["likely_edit_files"] = extras.Hints.LikelyEditFiles
210		}
211		if len(extras.Hints.LikelyTestFiles) > 0 {
212			payload["likely_test_files"] = extras.Hints.LikelyTestFiles
213		}
214		if len(extras.Hints.ActionChecklist) > 0 {
215			payload["action_checklist"] = extras.Hints.ActionChecklist
216		}
217		if len(extras.Related) > 0 {
218			payload["related_patterns"] = extras.Related
219		}
220		if len(rows) == 0 && extras.BlindSpot != "" {
221			payload["blind_spot"] = extras.BlindSpot
222		}
223		return payload
224	}
