226	func cloneRetrievalTransportExtras(extras retrievalTransportExtras) retrievalTransportExtras {
227		extras.AbstractPreviews = append([]sessionAbstractPreview(nil), extras.AbstractPreviews...)
228		extras.Hints.LikelyEditFiles = append([]string(nil), extras.Hints.LikelyEditFiles...)
229		extras.Hints.LikelyTestFiles = append([]string(nil), extras.Hints.LikelyTestFiles...)
230		extras.Hints.ActionChecklist = append([]brainBriefAction(nil), extras.Hints.ActionChecklist...)
231		extras.Related = append([]relatedPatternRef(nil), extras.Related...)
232		return extras
233	}
234	
235	// trimRetrievalExtrasOnce drops one lowest-priority optional tail item. This
236	// gives the caller a useful bounded response even when previews or discovery
237	// pointers consume the budget before any ranked row does.
238	func trimRetrievalExtrasOnce(extras *retrievalTransportExtras) bool {
239		switch {
240		case len(extras.AbstractPreviews) > 0:
241			extras.AbstractPreviews = extras.AbstractPreviews[:len(extras.AbstractPreviews)-1]
242			extras.AbstractPreviewsTruncated = true
243		case len(extras.Related) > 0:
244			extras.Related = extras.Related[:len(extras.Related)-1]
245		case len(extras.Hints.ActionChecklist) > 0:
246			extras.Hints.ActionChecklist = extras.Hints.ActionChecklist[:len(extras.Hints.ActionChecklist)-1]
247		case len(extras.Hints.LikelyTestFiles) > 0:
248			extras.Hints.LikelyTestFiles = extras.Hints.LikelyTestFiles[:len(extras.Hints.LikelyTestFiles)-1]
249		case len(extras.Hints.LikelyEditFiles) > 0:
250			extras.Hints.LikelyEditFiles = extras.Hints.LikelyEditFiles[:len(extras.Hints.LikelyEditFiles)-1]
251		case extras.BlindSpot != "":
252			extras.BlindSpot = ""
253		default:
254			return false
255		}
256		return true
257	}
258	
259	// countRetrievalExtrasTrims reports how many steps trimRetrievalExtrasOnce
260	// can apply to extras before it is exhausted.
261	func countRetrievalExtrasTrims(extras retrievalTransportExtras) int {
262		ex := cloneRetrievalTransportExtras(extras)
263		n := 0
264		for trimRetrievalExtrasOnce(&ex) {
265			n++
266		}
267		return n
268	}
269	
270	// smallestTrimStepsThatFit finds the fewest trim steps, between 1 and
271	// maxSteps, whose rendering fits the response budget. Trimming is monotone —
272	// every step only removes content — so once some step count fits, every
273	// larger one fits, and a binary search returns the same state the former
274	// one-step-at-a-time loop reached while rendering O(log n) candidates
275	// instead of O(n). sizeAt must rebuild from pristine inputs so probes are
276	// order-independent. The untrimmed rendering is the caller's job to check
277	// first: step one adds the truncation marker and can grow the output.
278	func smallestTrimStepsThatFit(maxSteps int, sizeAt func(int) (int, error)) (int, bool, error) {
279		if maxSteps < 1 {
280			return 0, false, nil
281		}
282		if size, err := sizeAt(maxSteps); err != nil || size > conversationConceptResponseMaxBytes {
283			return 0, false, err
284		}
285		lo, hi := 1, maxSteps
286		for lo < hi {
287			mid := (lo + hi) / 2
288			size, err := sizeAt(mid)
289			if err != nil {
290				return 0, false, err
291			}
292			if size <= conversationConceptResponseMaxBytes {
293				hi = mid
294			} else {
295				lo = mid + 1
296			}
297		}
298		return lo, true, nil
299	}
300	
301	// boundedRetrievalJSONPayload removes optional extras, then whole tail rows,
302	// until the exact serialization fits. The response_truncated marker is
303	// present during every truncated size check, so the marker itself can never
304	// push the emitted document over budget.
305	func boundedRetrievalJSONPayload(query, branch string, results []unifiedResult, extras retrievalTransportExtras) (map[string]any, error) {
306		allRows := retrieval.CompactResults(results, query)
307		extras = cloneRetrievalTransportExtras(extras)
308		extrasSteps := countRetrievalExtrasTrims(extras)
309		build := func(steps int) map[string]any {
310			ex := cloneRetrievalTransportExtras(extras)
311			for i := 0; i < min(steps, extrasSteps); i++ {
312				trimRetrievalExtrasOnce(&ex)
313			}
314			rows := append([]compactUnifiedResult{}, allRows[:len(allRows)-max(steps-extrasSteps, 0)]...)
315			return buildRetrievalJSONPayload(query, branch, rows, ex, steps > 0)
316		}
317		sizeAt := func(steps int) (int, error) {
318			data, err := cmdutil.JSONOutputBytes(build(steps))
319			if err != nil {
320				return 0, err
321			}
322			return len(data), nil
323		}
324		if size, err := sizeAt(0); err != nil {
325			return nil, err
326		} else if size <= conversationConceptResponseMaxBytes {
327			return build(0), nil
328		}
329		steps, ok, err := smallestTrimStepsThatFit(extrasSteps+len(allRows), sizeAt)
330		if err != nil {
331			return nil, err
332		}
333		if !ok {
334			return nil, fmt.Errorf("retrieval response envelope exceeds %d bytes without any result rows", conversationConceptResponseMaxBytes)
335		}
336		return build(steps), nil
337	}
338	
339	type retrievalIDQualifier func(string) string
340	
341	func identityRetrievalID(id string) string { return id }
342	
343	// renderRetrievalRowsText is shared by single-repo and workspace text modes,
344	// keeping the multi-concept proof contract at parity. Every proof line is independently
345	// bounded even though concepts and identifiers already have stricter input
346	// limits.
347	func renderRetrievalRowsText(out io.Writer, results []unifiedResult, qualify retrievalIDQualifier) {
348		if qualify == nil {
349			qualify = identityRetrievalID
350		}
351		for _, result := range results {
352			ex := base.TruncateString(strings.Join(strings.Fields(result.Text), " "), 200)
353			label := result.Source
354			if result.VerificationRequired {
355				label += " verify"
356			}
357			fmt.Fprintf(out, "[%s] %s  %s\n    %s\n", label, qualify(result.ID), retrieval.ResultLocation(result), ex)
358			retrieval.PrintResultCaveats(out, result)
359			if len(result.Concepts) == 0 {
360				continue
361			}
362			concepts, _ := truncateUTF8Bytes(strings.Join(result.Concepts, " | "), 3*1024)
363			fmt.Fprintf(out, "    proof concepts=%s worst_rank=%d rank_sum=%d approximate=%t\n", concepts, result.WorstRank, result.RankSum, result.Approximate)
364			for _, match := range result.ConceptMatches {
365				terms, _ := truncateUTF8Bytes(strings.Join(match.MatchedTerms, ","), 1024)
366				concept, _ := truncateUTF8Bytes(match.Concept, conversationConceptMaxBytes)
367				fmt.Fprintf(out, "    proof concept=%q evidence=%s rank=%d arm=%s matched_terms=%s\n",
368					concept, qualify(match.ConversationID), match.Rank, match.Arm, terms)
369			}
370			if len(result.EvidenceIDs) > 0 {
371				ids := make([]string, len(result.EvidenceIDs))
372				for i, id := range result.EvidenceIDs {
373					ids[i] = qualify(id)
374				}
375				fmt.Fprintf(out, "    evidence_ids=%s\n", strings.Join(ids, ","))
376			}
377		}
378	}
379	
380	func filteredAbstractPreviewsForResults(previews []sessionAbstractPreview, results []unifiedResult) ([]sessionAbstractPreview, bool) {
381		rows := retrieval.CompactResults(results, "")
382		return filterAbstractPreviewsForRows(previews, rows)
383	}
384	
385	func renderSingleRepoRetrievalText(query string, results []unifiedResult, extras retrievalTransportExtras, truncated bool) []byte {
386		var out bytes.Buffer
387		if len(results) == 0 && !truncated {
388			fmt.Fprintf(&out, "no results for %q\n", query)
389			if extras.BlindSpot != "" {
390				fmt.Fprintln(&out, extras.BlindSpot)
391			}
392		}
393		hints := extras.Hints
394		for _, file := range hints.LikelyEditFiles {
395			fmt.Fprintf(&out, "edit_file %s\n", file)
396		}
397		for _, file := range hints.LikelyTestFiles {
398			fmt.Fprintf(&out, "test_file %s\n", file)
399		}
400		for _, action := range hints.ActionChecklist {
401			fmt.Fprintf(&out, "action %s %s: %s\n", action.File, action.Symbol, action.Action)
402		}
403		renderRetrievalRowsText(&out, results, nil)
404		for _, pattern := range extras.Related {
405			fmt.Fprintf(&out, "related [%s] %s  %s\n", pattern.Type, pattern.ID, pattern.Title)
406		}
407		previews, previewCut := filteredAbstractPreviewsForResults(extras.AbstractPreviews, results)
408		for _, preview := range previews {
409			text := ""
410			if preview.Overview != nil {
411				text = "  " + strings.Join(strings.Fields(preview.Overview.Text), " ")
412			}
413			fmt.Fprintf(&out, "abstract [%s] %s%s\n", preview.AbstractStatus, preview.SessionRef, text)
414			if preview.AbstractIssue != "" {
415				issue, _ := truncateUTF8Bytes(strings.Join(strings.Fields(preview.AbstractIssue), " "), 1024)
416				fmt.Fprintf(&out, "  automatic enqueue issue: %s\n", issue)
417			}
418		}
419		if extras.AbstractPreviewsTruncated || previewCut {
420			fmt.Fprintln(&out, "abstract previews truncated")
421		}
422		fmt.Fprintf(&out, "response_truncated %t\n", truncated)
423		return out.Bytes()
424	}
425	
426	func boundedSingleRepoRetrievalText(query string, results []unifiedResult, extras retrievalTransportExtras) ([]byte, error) {
427		extras = cloneRetrievalTransportExtras(extras)
428		extrasSteps := countRetrievalExtrasTrims(extras)
429		render := func(steps int) []byte {
430			ex := cloneRetrievalTransportExtras(extras)
431			for i := 0; i < min(steps, extrasSteps); i++ {
432				trimRetrievalExtrasOnce(&ex)
433			}
434			count := len(results) - max(steps-extrasSteps, 0)
435			return renderSingleRepoRetrievalText(query, results[:count], ex, steps > 0)
436		}
437		if data := render(0); len(data) <= conversationConceptResponseMaxBytes {
438			return data, nil
439		}
440		steps, ok, err := smallestTrimStepsThatFit(extrasSteps+len(results), func(steps int) (int, error) {
441			return len(render(steps)), nil
442		})
443		if err != nil {
444			return nil, err
445		}
446		if !ok {
447			return nil, fmt.Errorf("retrieval text envelope exceeds %d bytes without any result rows", conversationConceptResponseMaxBytes)
448		}
449		return render(steps), nil
450	}
451	
452	// boundedRetrievalResponseBytes renders the budget-bounded multi-concept
453	// response in either output mode; the extracted retrieve commands inject it as
454	// Deps.BoundedResponseBytes, keeping the trim/assembly machinery in cli with
455	// the transport layer.
456	func boundedRetrievalResponseBytes(query, branch string, results []unifiedResult, extras retrievalTransportExtras, jsonOut bool) ([]byte, error) {
457		if jsonOut {
458			payload, err := boundedRetrievalJSONPayload(query, branch, results, extras)
459			if err != nil {
460				return nil, err
461			}
462			return cmdutil.JSONOutputBytes(payload)
463		}
464		return boundedSingleRepoRetrievalText(query, results, extras)
465	}
466	
467	func qualifyWorkspaceAddressableID(repoKey, workspaceName, id string) string {
468		id = strings.TrimSpace(id)
469		if id == "" || strings.HasPrefix(id, repoKey+"/") {
470			return id
471		}
472		if repoKey == workspaceName && (strings.HasPrefix(id, "graph:") || strings.HasPrefix(id, "pattern:") || strings.HasPrefix(id, "theme:")) {
473			return id
474		}
475		return repoKey + "/" + id
476	}
477	
478	func qualifyAbstractStatement(repoKey, workspaceName string, statement abstractStatement) abstractStatement {
479		statement.EvidenceIDs = append([]string(nil), statement.EvidenceIDs...)
480		for i := range statement.EvidenceIDs {
481			statement.EvidenceIDs[i] = qualifyWorkspaceAddressableID(repoKey, workspaceName, statement.EvidenceIDs[i])
482		}
483		return statement
484	}
485	
486	// qualifyWorkspaceUnifiedResult recursively qualifies every addressable id,
487	// not merely the top-level hit. A nested concept proof, session turn, related
488	// id, or abstract citation can therefore be pasted directly into workspace
489	// get without reconstructing the member namespace.
490	func qualifyWorkspaceUnifiedResult(repoKey, workspaceName string, result unifiedResult) unifiedResult {
491		qualify := func(id string) string { return qualifyWorkspaceAddressableID(repoKey, workspaceName, id) }
492		result.ID = qualify(result.ID)
493		result.SessionRef = qualify(result.SessionRef)
494		result.TargetID = qualify(result.TargetID)
495		result.RelatedIDs = append([]string(nil), result.RelatedIDs...)
496		for i := range result.RelatedIDs {
497			result.RelatedIDs[i] = qualify(result.RelatedIDs[i])
498		}
499		result.EvidenceIDs = append([]string(nil), result.EvidenceIDs...)
500		for i := range result.EvidenceIDs {
501			result.EvidenceIDs[i] = qualify(result.EvidenceIDs[i])
502		}
503		result.ConceptMatches = append([]conceptMatch(nil), result.ConceptMatches...)
504		for i := range result.ConceptMatches {
505			result.ConceptMatches[i].ConversationID = qualify(result.ConceptMatches[i].ConversationID)
506			result.ConceptMatches[i].MatchedTerms = append([]string(nil), result.ConceptMatches[i].MatchedTerms...)
507		}
508		result.Turns = append([]conversationTurn(nil), result.Turns...)
509		for i := range result.Turns {
510			result.Turns[i].ConversationID = qualify(result.Turns[i].ConversationID)
511		}
512		if result.Abstract != nil {
513			abstract := *result.Abstract
514			abstract.SessionRef = qualify(abstract.SessionRef)
515			abstract.Overview = qualifyAbstractStatement(repoKey, workspaceName, abstract.Overview)
516			abstract.Outcomes = append([]abstractStatement(nil), abstract.Outcomes...)
517			for i := range abstract.Outcomes {
518				abstract.Outcomes[i] = qualifyAbstractStatement(repoKey, workspaceName, abstract.Outcomes[i])
519			}
520			abstract.Decisions = append([]abstractStatement(nil), abstract.Decisions...)
521			for i := range abstract.Decisions {
522				abstract.Decisions[i] = qualifyAbstractStatement(repoKey, workspaceName, abstract.Decisions[i])
523			}
524			abstract.Unresolved = append([]abstractStatement(nil), abstract.Unresolved...)
525			for i := range abstract.Unresolved {
526				abstract.Unresolved[i] = qualifyAbstractStatement(repoKey, workspaceName, abstract.Unresolved[i])
527			}
528			result.Abstract = &abstract
529		}
530		return result
531	}
532	
533	func qualifyWorkspacePreview(repoKey, workspaceName string, preview sessionAbstractPreview) sessionAbstractPreview {
534		preview.SessionRef = qualifyWorkspaceAddressableID(repoKey, workspaceName, preview.SessionRef)
535		if preview.Overview != nil {
536			overview := qualifyAbstractStatement(repoKey, workspaceName, *preview.Overview)
537			preview.Overview = &overview
538		}
539		return preview
540	}
541	
542	func qualifyWorkspaceRetrieveGroups(workspaceName string, groups []workspaceRetrieveResult) []workspaceRetrieveResult {
543		out := make([]workspaceRetrieveResult, len(groups))
544		for i, group := range groups {
545			out[i] = group
546			out[i].Results = make([]unifiedResult, len(group.Results))
547			for j, result := range group.Results {
548				out[i].Results[j] = qualifyWorkspaceUnifiedResult(group.RepoKey, workspaceName, result)
549			}
550			out[i].AbstractPreviews = make([]sessionAbstractPreview, len(group.AbstractPreviews))
551			for j, preview := range group.AbstractPreviews {
552				out[i].AbstractPreviews[j] = qualifyWorkspacePreview(group.RepoKey, workspaceName, preview)
553			}
554		}
555		return out
556	}
557	
558	func trimWorkspaceGroupsToCount(groups []workspaceRetrieveResult, keep int, truncated bool) []workspaceRetrieveResult {
559		out := make([]workspaceRetrieveResult, len(groups))
560		remaining := keep
561		lastGroup, lastRow := -1, -1
562		for i, group := range groups {
563			out[i] = group
564			count := min(remaining, len(group.Results))
565			out[i].Results = append([]unifiedResult(nil), group.Results[:count]...)
566			remaining -= count
567			if count > 0 {
568				lastGroup, lastRow = i, count-1
569			}
570			refs := map[string]bool{}
571			for _, result := range out[i].Results {
572				if result.SessionRef != "" {
573					refs[result.SessionRef] = true
574				}
575			}
576			previews := make([]sessionAbstractPreview, 0, len(group.AbstractPreviews))
577			for _, preview := range group.AbstractPreviews {
578				if refs[preview.SessionRef] {
579					previews = append(previews, preview)
580				}
581			}
582			out[i].AbstractPreviews = previews
583			out[i].AbstractPreviewsTruncated = group.AbstractPreviewsTruncated || len(previews) != len(group.AbstractPreviews)
584		}
585		if truncated && lastGroup >= 0 {
586			out[lastGroup].Results[lastRow].ResponseTruncated = true
587		}
588		return out
589	}
590	
591	func cloneWorkspaceRetrieveGroups(groups []workspaceRetrieveResult) []workspaceRetrieveResult {
592		out := make([]workspaceRetrieveResult, len(groups))
593		for i, group := range groups {
594			out[i] = group
595			out[i].Results = append([]unifiedResult(nil), group.Results...)
596			out[i].AbstractPreviews = append([]sessionAbstractPreview(nil), group.AbstractPreviews...)
597		}
598		return out
599	}
600	
601	// trimWorkspaceExtrasOnce drops one lowest-priority optional tail item so the
602	// caller keeps a useful bounded response. A member's Error is deliberately NOT
603	// trimmable: clearing it makes a member whose retrieval failed serialize as
604	// {"results": []}, byte-identical to a healthy member with no matches, and the
605	// generic response_truncated marker does not say a failure was suppressed.
606	// Ranked rows are the cheap thing to drop; a member's failure is not.
607	func trimWorkspaceExtrasOnce(groups []workspaceRetrieveResult) bool {
608		for i := len(groups) - 1; i >= 0; i-- {
609			switch {
610			case len(groups[i].AbstractPreviews) > 0:
611				groups[i].AbstractPreviews = groups[i].AbstractPreviews[:len(groups[i].AbstractPreviews)-1]
612				groups[i].AbstractPreviewsTruncated = true
613				return true
614			case groups[i].Freshness.Detail != "":
615				groups[i].Freshness.Detail = ""
616				return true
617			case groups[i].Freshness.ContractDetail != "":
618				groups[i].Freshness.ContractDetail = ""
619				return true
620			}
621		}
622		return false
623	}
624	
625	// countWorkspaceExtrasTrims reports how many steps trimWorkspaceExtrasOnce
626	// can apply to groups before it is exhausted.
627	func countWorkspaceExtrasTrims(groups []workspaceRetrieveResult) int {
628		gs := cloneWorkspaceRetrieveGroups(groups)
629		n := 0
630		for trimWorkspaceExtrasOnce(gs) {
631			n++
632		}
633		return n
634	}
635	
636	// applyWorkspaceTrimSteps rebuilds the trim state after `steps` steps of the
637	// deterministic sequence shared by both workspace surfaces: optional extras
638	// first, then one kept row at a time, then whole tail groups.
639	func applyWorkspaceTrimSteps(pristine []workspaceRetrieveResult, extrasSteps, total, steps int) (groups []workspaceRetrieveResult, keep int) {
640		gs := cloneWorkspaceRetrieveGroups(pristine)
641		for i := 0; i < min(steps, extrasSteps); i++ {
642			trimWorkspaceExtrasOnce(gs)
643		}
644		rowDrops := min(max(steps-extrasSteps, 0), total)
645		groupDrops := max(steps-extrasSteps-total, 0)
646		return gs[:len(gs)-groupDrops], total - rowDrops
647	}
648	
649	func boundedWorkspaceRetrievalJSONPayload(workspaceName, query string, groups []workspaceRetrieveResult) (map[string]any, error) {
650		qualified := cloneWorkspaceRetrieveGroups(qualifyWorkspaceRetrieveGroups(workspaceName, groups))
651		total := 0
652		for _, group := range qualified {
653			total += len(group.Results)
654		}
655		extrasSteps := countWorkspaceExtrasTrims(qualified)
656		build := func(steps int) map[string]any {
657			gs, keep := applyWorkspaceTrimSteps(qualified, extrasSteps, total, steps)
658			payload := map[string]any{
659				"workspace": workspaceName,
660				"query":     query,
661				"results":   trimWorkspaceGroupsToCount(gs, keep, steps > 0),
662			}
663			if steps > 0 {
664				payload["response_truncated"] = true
665			}
666			return payload
667		}
668		sizeAt := func(steps int) (int, error) {
669			data, err := cmdutil.JSONOutputBytes(build(steps))
670			if err != nil {
671				return 0, err
672			}
673			return len(data), nil
674		}
675		if size, err := sizeAt(0); err != nil {
676			return nil, err
677		} else if size <= conversationConceptResponseMaxBytes {
678			return build(0), nil
679		}
680		steps, ok, err := smallestTrimStepsThatFit(extrasSteps+total+len(qualified), sizeAt)
681		if err != nil {
682			return nil, err
683		}
684		if !ok {
685			return nil, fmt.Errorf("workspace retrieval response envelope exceeds %d bytes without any result rows", conversationConceptResponseMaxBytes)
686		}
687		return build(steps), nil
688	}
689	
690	func renderWorkspaceRetrievalText(workspaceName string, groups []workspaceRetrieveResult, keep int, truncated bool) []byte {
691		var out bytes.Buffer
692		remaining := keep
693		for _, group := range groups {
694			count := min(remaining, len(group.Results))
695			remaining -= count
696			qualify := func(id string) string { return qualifyWorkspaceAddressableID(group.RepoKey, workspaceName, id) }
697			renderRetrievalRowsText(&out, group.Results[:count], qualify)
698			if group.Error != "" {
699				fmt.Fprintf(&out, "%s error %s\n", group.RepoKey, group.Error)
700			}
701		}
702		fmt.Fprintf(&out, "response_truncated %t\n", truncated)
703		return out.Bytes()
704	}
705	
706	func boundedWorkspaceRetrievalText(workspaceName string, groups []workspaceRetrieveResult) ([]byte, error) {
707		groups = cloneWorkspaceRetrieveGroups(groups)
708		total := 0
709		for _, group := range groups {
710			total += len(group.Results)
711		}
712		extrasSteps := countWorkspaceExtrasTrims(groups)
713		render := func(steps int) []byte {
714			gs, keep := applyWorkspaceTrimSteps(groups, extrasSteps, total, steps)
715			return renderWorkspaceRetrievalText(workspaceName, gs, keep, steps > 0)
716		}
717		if data := render(0); len(data) <= conversationConceptResponseMaxBytes {
718			return data, nil
719		}
720		steps, ok, err := smallestTrimStepsThatFit(extrasSteps+total+len(groups), func(steps int) (int, error) {
721			return len(render(steps)), nil
722		})
723		if err != nil {
724			return nil, err
725		}
726		if !ok {
727			return nil, fmt.Errorf("workspace retrieval text envelope exceeds %d bytes without any result rows", conversationConceptResponseMaxBytes)
728		}
729		return render(steps), nil
730	}
