// brainBriefPatternsCount caps how many task-relevant patterns the brief carries.
func brainBriefPatternsCount(limit int) int {
	if limit <= 0 || limit > 5 {
		return 5
	}
	return limit
}

// rankTaskRelevantPatterns returns the patterns whose title/kind share a term
// with the task, ranked by term overlap then strength. Patterns with no overlap
// are dropped — the brief should surface task-relevant patterns, not ambient
// noise — so an unrelated task yields none.
func rankTaskRelevantPatterns(views []patternView, terms []string, limit int) []patternView {
	if limit <= 0 || len(terms) == 0 {
		return nil
	}
	termSet := make(map[string]bool, len(terms))
	for _, t := range terms {
		termSet[t] = true
	}
	type scored struct {
		v       patternView
		overlap int
	}
	var matched []scored
	for _, v := range views {
		seen := map[string]bool{}
		overlap := 0
		for _, w := range brainBriefTaskWordPattern.FindAllString(strings.ToLower(v.Title+" "+v.Kind), -1) {
			if termSet[w] && !seen[w] {
				seen[w] = true
				overlap++

			for i, t := range tasks {
				redacted[i] = redactCandidate(t)
			}
			return cmdutil.WriteJSON(cmd, redacted)
		}
		out := cmd.OutOrStdout()
		if len(tasks) == 0 {
			if corpusBacked {
				fmt.Fprintln(out, "no skill proposals: promotable tasks need an accepted deep dossier.\nRun `"+base.BrainInvocation(os.LookupEnv, "patterns verify")+" --deep` (explicit, egress-gated), then re-check.")
			} else {
				fmt.Fprintln(out, "no task candidates (run `"+base.BrainInvocation(os.LookupEnv, "patterns refresh")+"`)")
			}
			return nil
		}
		for _, t := range tasks {
			r := t.Reinforcement
			fmt.Fprintf(out, "[%s] %s  (strength %.2f)\n", t.StrengthLabel, base.RedactText(t.Label), t.Strength)
			fmt.Fprintf(out, "    %d session(s), %d with commands; %d↑ %d↓ %d·; commands: %s\n",
				t.Support, t.WithCommands, r.Success, r.Corrected, r.Neutral, base.RedactText(joinMax(t.Commands, 5)))
			fmt.Fprintf(out, "    id %s\n", t.ID)
		}
		return nil
	})
}

func runPatternsSkillsForm(ctx context.Context, cmd *cobra.Command, opts Options, target string, s skillFormOptions) error {
	repoDir, local, err := base.ResolveLocalTargetRepoDir(ctx, opts.Runner, target)
	if err != nil {
		return err
	}
	if !local {
		return fmt.Errorf("patterns skills form requires a local repository path: %s", target)
	}
	storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
	if err != nil {
		return err
	}
	brainDir := storage.BrainDir
	privacyPolicy, err := brainstore.CaptureRetrievalPrivacyPolicy(brainDir)
	if err != nil {
		return err
	}
	privacyPolicy.RequireDerivedClean = true
	if err := requirePrivacyDerivedRead(brainDir); err != nil {
		return err
	}
	return runPrivacyLinearizedPatternMutation(cmd, []retrievalPrivacyPolicy{privacyPolicy}, func() error {
		var cand *taskCandidate
		var deep *deepSkillInput
		// A theme skill is synthesized from the verified latent practice (its agent
		// description), not a raw intent_sig.
		if strings.HasPrefix(s.taskID, "theme:") {
			in, ok, err := loadAcceptedThemeAsDeepChecked(brainDir, s.taskID)
			if err != nil {
				return err
			}
			if !ok {
				return fmt.Errorf("no accepted theme %q: run `"+base.BrainInvocation(os.LookupEnv, "patterns verify")+" --themes` first", s.taskID)
			}
			deep = &in
			cand = &taskCandidate{ID: s.taskID, Label: in.rec.Title}
			agent := s.agent
			if agent == "" || agent == "auto" {
				agent = defaultRefreshAgent(ctx, opts.Runner, repoDir)
			}
			if agent == "none" {
				return fmt.Errorf("skill synthesis requires an agent (codex or claude-code); none found on PATH")
			}
			return synthesizeAndForm(ctx, cmd, *cand, deep, nil, brainDir, repoDir, agent, defaultDistillAgentRunner(agent), s, opts.Now().UTC())
		}
		// Knowledge-sourced skills (procedure lessons / capability conventions) are
		// stored as accepted deep dossiers under their own ids — synthesize by
		// converting the verified record.
		if strings.HasPrefix(s.taskID, "lesson:") || strings.HasPrefix(s.taskID, "convention:") {
			in, ok, err := loadAcceptedDeepDossierChecked(brainDir, s.taskID)
			if err != nil {
				return err
			}
			if !ok {
				channel := "--lessons"
				if strings.HasPrefix(s.taskID, "convention:") {
					channel = "--conventions"
				}
				return fmt.Errorf("no accepted proposal %q: run `"+base.BrainInvocation(os.LookupEnv, "patterns verify")+" %s` first", s.taskID, channel)
			}
			deep = &in
			cand = &taskCandidate{ID: s.taskID, Label: in.rec.Title, Support: in.rec.EvidenceEpisodes}
			agent := s.agent
			if agent == "" || agent == "auto" {
				agent = defaultRefreshAgent(ctx, opts.Runner, repoDir)
			}
			if agent == "none" {
				return fmt.Errorf("skill synthesis requires an agent (codex or claude-code); none found on PATH")
			}
			return synthesizeAndForm(ctx, cmd, *cand, deep, nil, brainDir, repoDir, agent, defaultDistillAgentRunner(agent), s, opts.Now().UTC())
		}
		c, corpusBacked, err := corpusTaskCandidateByIDChecked(brainDir, s.taskID)
		if err != nil {
			return err
		}
		if corpusBacked {
			cand = c
			// Corpus-backed skills MUST come from a verified deep dossier — never
			// silently from shallow corpus rows.
			if in, ok, err := loadAcceptedDeepDossierChecked(brainDir, s.taskID); err != nil {
				return err
			} else if ok {
				deep = &in
			} else {
				return fmt.Errorf("needs deep verification first: %s has no accepted deep dossier.\n"+
					"Run `"+base.BrainInvocation(os.LookupEnv, "patterns verify")+" --deep` (explicit, egress-gated), then re-run this form.", s.taskID)

		RunE: func(cmd *cobra.Command, args []string) error {
			return runWorkspacePatternsVerify(cmd.Context(), cmd, opts, args[0], v.agent, v.model, v.effort, v.asJSON)
		},
	}
	verify.Flags().StringVar(&v.agent, "agent", "auto", "Judgment agent: auto, codex, claude-code, ollama, or command")
	verify.Flags().StringVar(&v.model, "model", "", "Override the agent model")
	verify.Flags().StringVar(&v.effort, "effort", "", "Agent reasoning effort")
	verify.Flags().BoolVar(&v.asJSON, "json", false, "Emit the verification summary as JSON")
	skills := newWorkspaceSkillsCommand(opts)

	cmd.AddCommand(refresh, status, verify, skills)
	return cmd
}

