	if err != nil {
		return err
	}
	if !present {
		return RejectInterruptedCorpusPublication(brainDir)
	}
	_, _, err = brainstore.PrivacyArtifactInfo(brainDir, CorpusPath+"-wal", "pattern corpus WAL")
	if err != nil {
		return err
	}
