61		var retained map[string]bool
62		retain := func(rel, reason string) {
63			tui.Warnf(os.Stderr, "retain transcript cache: %s for %s; keeping the cached copy", reason, rel)
64			if retained == nil {
65				retained = make(map[string]bool)
66			}
67			retained[rel] = true
68		}
