78			}
79			if _, live := sessions[file.Rel]; !live {
80				continue
81			}
82			location, snapshot, err := store.lookupLocation(ctx, file.Rel)
83			if err != nil {
84				if backed {
85					retain(file.Rel, "checkpoint copy is unavailable")
86					continue
87				}
88				return nil, fmt.Errorf("retain transcript cache: %w", err)
89			}
90			data, err := readSnapshotTranscriptFromSource(ctx, runner, snapshot, location.sourceKey, location.sourcePath)
91			if err != nil {
