555	func historyIndexCurrent(brainDir string, manifest *exportManifest) bool {
556		if manifest == nil || manifest.Sources == nil || manifest.Sources.Sessions == nil || manifest.Sources.History == nil {
557			return false
558		}
559		history := manifest.Sources.History
560		if history.IndexPath == "" || history.SessionsFingerprint == "" || history.IndexBytes <= 0 ||
561			!historystore.ValidSHA256(history.IndexSHA256) || !historystore.ValidSHA256(history.RecordsFingerprint) ||
562			!historystore.ValidSHA256(history.TranscriptsFingerprint) {
563			return false
564		}
565		if history.SessionsFingerprint != sessionSourceFingerprint(manifest.Sources.Sessions) {
566			return false
567		}
568		clean, err := historystore.ValidateIndexPath(history.IndexPath)
569		if err != nil {
570			return false
571		}
572		if err := base.RejectSymlinkPathComponents(brainDir, clean); err != nil {
573			return false
574		}
575		indexPath := filepath.Join(brainDir, clean)
576		info, err := os.Stat(indexPath)
577		if err != nil || !info.Mode().IsRegular() || info.Size() != history.IndexBytes {
578			return false
579		}
580		// Unsafe/unreadable entries are deliberately excluded by the same collector
581		// used to build the index. Comparing the safe included set keeps those
582		// exclusions fail-closed without forcing an endless rebuild.
583		stones, _, err := brainstore.LoadSessionTombstonesChecked(brainDir)
584		if err != nil {
585			return false
586		}
587		excludedByPath, err := excludedTranscriptPathsChecked(brainDir, manifest, stones)
588		if err != nil {
589			return false
590		}
591		files, err := collectHistorySessionDigests(context.Background(), brainDir, excludedByPath)
592		if err != nil {
593			return false
594		}
595		return historyTranscriptFilesFingerprint(files) == history.TranscriptsFingerprint
596	}
597	
