		if h.ID == "" || seen[h.ID] || historystore.GuardBlocksRecord(guard, h) {
			continue
		}
		seen[h.ID] = true
		recs = append(recs, h)
	}
	total := len(recs)
	trunc := limit > 0 && total > limit

