	}
	manifest, err := bmanifest.Load(outputDir)
	if err != nil {
		return historyProjectionIdentity{}, nil, sessionTombstones{}, err
	}
	inventory, err := collectHistorySessionInventory(ctx, outputDir)
	if err != nil {
		if errors.Is(err, errHistorySessionsRootMissing) {
