	if d.IsDir() {
		name := d.Name()
		if name == semstore.DirName || name == ".git" {
			return filepath.SkipDir
		}
		return nil
	}
	if report.Scanned >= brainInspectHistoryMaxFiles || len(report.Matches) >= maxHits {
		report.Truncated = true
		return filepath.SkipAll
	}
